const d = $input.first().json;
const msg = (d.execution?.error?.message || '').toString();
const node = d.execution?.lastNodeExecuted || 'unknown';
const wf = d.workflow?.name || 'unknown';

const critical = /401|403|unauthori[sz]ed|invalid[_ ]?token|oauth|credential|expired|insufficient|payment|quota/i.test(msg);
const crmFail = /zoho|crm/i.test(node);
// Non-critical: enrichment nodes already have fallbacks, so don't wake anyone up unless it's an auth/quota issue
const suppress = /apollo|hunter|enrich/i.test(node) && !critical;

// Throttle: same error at most once per 30 min
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const key = `${wf}|${node}|${msg.slice(0, 80)}`;
const now = Date.now();
const throttled = now - (sd.seen[key] || 0) < 30 * 60 * 1000;
const shouldAlert = !suppress && !throttled;
if (shouldAlert) sd.seen[key] = now;
for (const k of Object.keys(sd.seen)) if (now - sd.seen[k] > 86400000) delete sd.seen[k];

return [{ json: { shouldAlert, severity: critical ? 'CRITICAL' : crmFail ? 'HIGH' : 'MEDIUM',
  wf, node, msg, url: d.execution?.url, executionId: d.execution?.id } }];

